n alignment\\r\\n\\r\\n* lodash-es version alignment + lockfile\",\"authorName\":\"Manuel Römer\",\"authorEmail\":\"30902964+manuelroemer@users.noreply.github.com\"},{\"hash\":\"c870113c006d16a2b879d507560631afc4eb1523\",\"date\":\"2021-03-26T20:13:20+01:00\",\"message\":\"Added a Service Worker, PWA-Manifest and Network-First Caching of static app shell files (#89)\",\"refs\":\"\",\"body\":\"* Rudimentary service worker integration into the app shell. Based on Google's Workbox project (stc).\\r\\n\\r\\n* Switch from Workbox's precaching strategy to a manual hybrid runtime/precache strategy.\\r\\n\\r\\n* Added PWA manifest to the app shell.\\r\\n\\r\\n* Updated default cache name.\\r\\n\\r\\n* Explicitly include the importmap URL in the precached app shell files in order to also have external URLs in place.\\r\\n\\r\\n* Fixed an issue with non-distinct precache URLs in cache.addAll().\\r\\n\\r\\n* Added PWA deps to openmrs.\",\"authorName\":\"Manuel Römer\",\"authorEmail\":\"30902964+manuelroemer@users.noreply.github.com\"}],\"totalCount\":8}"}],"tool_result_meta":[{"id":"toolu_01NsdewCAeKyXBv1XbEKcL8T","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
{"type":"assistant","message":{"model":"claude-haiku-5-5","id":"msg_011CgKMmRJTueZRq7FKznQp7","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01QWYwNRbdjqxqV18wz668xr","name":"mcp__falkon__list_commits","input":{"repo":"github.com/openmrs/openmrs-esm-patient-management","query":"cache","perPage":20},"caller":{"type":"direct"}}],"container":null,"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":2,"cache_creation_input_tokens":472,"cache_read_input_tokens":20985,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":472},"output_tokens":4,"service_tier":"standard","inference_geo":"global","speed":"standard"},"input_transformations":[],"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"016e43be-7f80-4a15-89b8-fee7fecf37c5","uuid":"ab0d0ed6-8d2b-44ca-86cd-7084bc32c191","timestamp":"2026-10-23T14:52:55.793Z","request_id":"req_011CgKMmR1M5UZ8gKHjtDAcU","wire_tool_inputs":{"toolu_01QWYwNRbdjqxqV18wz668xr":{"repo":"github.com/openmrs/openmrs-esm-patient-management","query":"cache","perPage":20}},"tool_use_meta":[{"id":"toolu_01QWYwNRbdjqxqV18wz668xr","display_name":"List Commits","server_display_name":"falkon-mcp-server","tool_name":"list_commits"}]}
{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01QWYwNRbdjqxqV18wz668xr","type":"tool_result","content":[{"type":"text","text":"{\"commits\":[{\"hash\":\"dd5904929a290cb02803caa63066d44e3fc126a7\",\"date\":\"2026-09-20T23:31:10+03:00\",\"message\":\"(fix) Refresh patient list memberships after adding a patient\",\"refs\":\"\",\"body\":\"The add-to-list modal invalidated the cohort member key with the global\\nmutate imported from swr. That function is bound to SWR's default\\ncache, while every hook rendered under the framework's component\\ndecorator lives in the decorator's provider cache, so the call found\\nnothing and the patient's list memberships stayed stale after the\\nsuccess snackbar. Take mutate from useSWRConfig instead, which is bound\\nto the provider cache.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"212bc5dd4941ceb5dfd45a79417f345763fa0940\",\"date\":\"2026-09-18T17:00:58-04:00\",\"message\":\"(chore) Switch to using GitHub Actions cache for Actions\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"ian.c.bacher@gmail.com\"},{\"hash\":\"ac5758f3ba0c6868eb414e715e279e3e9d96ee90\",\"date\":\"2026-09-14T15:55:43-04:00\",\"message\":\"(fix) Make patient search a little more light-weight (#2742)\",\"refs\":\"\",\"body\":\"Basically this does two things:\\n\\n1. Fetch a smaller representation for a visit that includes the minimum\\n   we need.\\n2. Makes the SWR cache hold visits returned for 3 minutes. The idea\\n   being that paging through a single search shouldn't need to refetch\\n   the visit status unless the user genuinely switches their attention\\n   to elsewhere.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"b8335ad593a4946dd297a88e00c1fd6e6d1fc4f0\",\"date\":\"2026-09-08T20:40:11+08:00\",\"message\":\"(fix) O3-5940: Don't offer queues a patient is already in (#2710)\",\"refs\":\"\",\"body\":\"* (fix) O3-5940: Don't offer queues a patient is already in\\n\\n* (fix) O3-5940: Don't submit a prefilled service before the entries load\\n\\nA service prefilled from the dashboard was submittable while the lookup of the\\npatient's queue entries was still in flight: the queues had loaded, so the\\npriority defaulted and the form was valid behind the Service skeleton, and a\\nquick submit posted a queue entry that the filter would have excluded a moment\\nlater. The priority default now waits for those entries, so submitting during\\nthat window fails validation instead of reaching the server.\\n\\n* (fix) O3-5940: Let the Service field carry the queue filtering on its own\\n\\nFiltering whole locations out of the Location dropdown required a second,\\nunscoped useQueues() call just to group queues by location, plus a reset\\neffect to clear a location that disappeared underneath the user. Drop both\\nand filter only the Service options, which already load scoped to the\\nselected location. When the patient is in every queue there, the select\\nrenders empty with helper text saying so, and the required error is\\nsuppressed so it does not replace that text on blur. The misconfiguration\\nnotice now keys off the unfiltered queue list, and the priority skeleton\\nwaits on the queue entries alongside the services.\\n\\nDuplicate submissions come back as a generic \\\"Invalid Submission\\\" message\\nwith the identifying code in globalErrors, so getErrorMessage appends those\\ncodes and the queue fields reuse isDuplicateQueueEntryError instead of\\nmatching the message alone.\\n\\n* (fix) O3-5940: Address review feedback on duplicate detection and the Service field\\n\\nRead the duplicate error code from `globalErrors`, where the backend actually\\nreports it, and keep `getErrorMessage` free of it so the code no longer leaks\\ninto the snackbar subtitle two modals build from it. Let a genuine validation\\nerror still surface on the Service field, with the \\\"already in every queue\\\"\\nmessage carried as its error text rather than suppressing `invalid`.\\n\\nAlso make `patientUuid` optional, since every caller passes a value that may be\\nundefined, and drop the `memoizedQueueLocations` memo: `useFhirFetchAll` returns\\na fresh array on every render, so its dependency never matched and the memo\\nnever once returned a cached value.\\n\\n* Fix duplicate-queue error messages and prefilled service edge case\\n\\n- Read globalErrors from the backend response so validation errors like\\n  \\\"already in this queue\\\" surface instead of a generic message.\\n- Clear a prefilled service selection once queue entries confirm the\\n  patient is already enrolled in it.\\n\\n* (fix) O3-5940: Warn when the active queue entry lookup fails\\n\\n---------\\n\\nCo-authored-by: Nethmi Rodrigo <nethmi@openmrs.org>\\nCo-authored-by: NethmiRodrigo <nethmi.dilinika@gmail.com>\",\"authorName\":\"Ujjawal Prabhat\",\"authorEmail\":\"UjjawalPrabhat1@gmail.com\"},{\"hash\":\"39be6d5abb7182bd5b3e08b8684aefb6e046542f\",\"date\":\"2026-06-01T17:40:34-04:00\",\"message\":\"(feat) O3-5714: Improve performance with multi-paged patient search results (#2554)\",\"refs\":\"\",\"body\":\"* O3-5714: Improve performance with multi-paged patient search results\\n\\nSeveral notable fixes for the compact-patient-search component:\\n\\n* Previously, each call to `useSWRInfinite()` was, in essence, returning\\n  new copies of existing data, which lead to unnecessary re-renders. This\\n  has been fixed by setting `keepPreviousData` to `true`\\n* Previously, when `useSWRInfinite()` set `isLoading` to `true`, all\\n  results were replaced with placeholder. Since this gets set to `true`\\n  even when, e.g., loading a second page of results, this resulted in\\n  unnecessary unmounts and recreations, which was both a memory leak and\\n  lead to a stampede of requests.\\n* All search results were previously rendered and retained. This leads\\n  to stampedes of secondary queries (e.g., for patient photos, queue\\n  status, visit status, etc.). Instead, this PR moves us to using list\\n  virtualization so that roughly 10-18 items are retained in a React\\n  query. Large scrolls backwards or forwards have some slight glitches\\n  as components are re-rendered, but the easiest way to fix this is in\\n  the components rendering the secondary queries themselves.\\n* Recent patients, however, are not virtualized at all, as we rely on\\n  this being a limited list that is safe to load.\\n* A mistake in the call to `useArrowNavigation()` resulted in the arrow\\n  keys only being usable for up to the number of `recentPatients`\\n* This PR adds additional component-level memoization where it makes\\n  sense to speed up rendering. In addition, in the context of search\\n  results, we re-tune SWR to more aggressively cache so that there's\\n  less need to re-try, e.g., patient photo queries\\n* Additionally, this PR makes two fixes the service queues banner tag.\\n  First, if it is rendered outside the patient chart, a wrapper component\\n  is used so no query needs to be issued. Second, the query that was\\n  used overfetched data, especially as the queue details in the modal\\n  are basically reloaded, so the representation has been updated to\\n  minimize the data requested. This is one of the biggest contributing\\n  components.\\n\\n* Fixes from code review\\n\\n* Address Copilot comment\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"47d2f46e9584bb21e616f22c67e3315c985bc433\",\"date\":\"2026-04-27T21:07:35-09:00\",\"message\":\"(fix) O3-5579: Isolate appointment cache per patient to prevent cross-patient data leakage (#2450)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"omeri innocent\",\"authorEmail\":\"innocentomeri08@gmail.com\"},{\"hash\":\"8a16c8613ca23503da3093165282cdfa5a6ad3a2\",\"date\":\"2026-03-04T00:15:13+03:00\",\"message\":\"(fix) Refresh queue banner on patient chart after serving (#2295)\",\"refs\":\"\",\"body\":\"When navigating to the patient chart after serving a queue entry,\\nthe patient banner showed stale queue information because the\\nuseQueueEntries hook returned cached SWR data before revalidation\\ncompleted. Dispatch `queue-entry-updated` on mount (gated to the\\npatient-chart context) so the hook refetches fresh data, matching\\nthe pattern already used by DefaultQueueTable.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"69634fa859a4dd50d67b02ac789de5e0476e2979\",\"date\":\"2026-02-18T16:54:24+03:00\",\"message\":\"(fix) O3-5433: Prevent stale queue-entry modal submissions (#2274)\",\"refs\":\"\",\"body\":\"* (fix) O3-5433: Prevent stale queue-entry modal submissions\\n\\nThe Move/Transition/Edit queue entry action modals received a queue entry\\nobject captured at table render time. If another user, browser tab, or\\nbackground task ended that entry before the modal was submitted, the backend\\nwould reject the request with a 500 error \\\"Cannot transition a queue entry\\nthat has already ended\\\".\\n\\nThis change adds stale-entry detection at modal open and on submit to prevent\\nthe above scenario. Specifically, it makes the following changes:\\n\\n- Prefetch queue entry by UUID on modal open; show loading/error/ended\\n  states and block the form when the entry is no longer active\\n- Refresh queue-entry caches when stale ended entries are detected\\n- Catch already-ended errors on submit as a fallback; warn, refresh, and\\n  close the modal\\n- Add synchronous submit re-entry guards (useRef) in action and confirm\\n  modals to prevent duplicate submissions\\n- Centralize queue-entry error parsing into `queue-entry-error.utils.ts`\\n- Extract shared queue-entry custom representation constant to avoid\\n  duplicate encoding\\n- Add tests for Move/Transition/Edit stale-entry gating and already-ended\\n  submit handling\\n\\n* (fix) Use getCoreTranslation for 'Close' button text\\n\\n\\\"Close\\\" is a common string already provided by the framework's core\\ntranslations. Use getCoreTranslation('close') instead of a local\\nt('close', 'Close') call to avoid duplicating the translation key\\nin this package.\\n\\n* (fix) Address review feedback\\n\\nStabilize useMutateQueueEntries by wrapping the returned function in\\nuseCallback and the return object in useMemo, so consumers get a stable\\nreference. This removes the eslint-disable-next-line workarounds in the\\nthree action modals.\\n\\nRemove the redundant isSubmittingRef double-submit guard from\\nQueueEntryActionModal and QueueEntryConfirmActionModal. The existing\\ndisabled={isSubmitting} state is sufficient to prevent duplicate\\nsubmissions.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"eb79923a3297dbdc677c87f2cb7236f6ba43a844\",\"date\":\"2025-09-11T00:13:04+03:00\",\"message\":\"(chore) Modernize GitHub Actions workflows\",\"refs\":\"\",\"body\":\"- Replace manual caching with built-in Node.js cache\\n- Standardize Node.js version format to '20.x'\\n- Simplify Playwright installation process\\n- Add descriptive step names with emojis\\n\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"1035f45ff4a778664d6d629a7679fc43046877a1\",\"date\":\"2025-09-09T17:10:56+03:00\",\"message\":\"(fix) O3-5014: Surface actual error messages from appointment status change API (#1963)\",\"refs\":\"\",\"body\":\"Previously, when users attempted to cancel missed appointments, generic error messages were displayed instead of the specific backend validation errors. Now the actual API exception message is properly extracted and shown to users.\\n\\n- Extract error messages from responseBody.error.message chain\\n- Remove square brackets from backend error formatting\\n- Surface specific validation errors like \\\"Appointment status can not be changed from Missed to Cancelled\\\"\\n- Fix SWR cache invalidation issues causing premature UI updates\\n- Enable retry capability by resetting loading state in error handler\\n- Modernize error handling with async/await pattern\\n\\nFixes issue where backend validation errors (e.g., missed appointments cannot be cancelled due to status sequence rules) were not properly communicated to users.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"bc9848228e577b6d480f8ab7a91abcf61941e884\",\"date\":\"2024-09-16T22:11:23+03:00\",\"message\":\"(chore) Set up local turborepo cache server for pre-release job\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"4e8fe5871828599ae51962c42f2fc7a86f8f27f7\",\"date\":\"2024-09-06T11:43:24+03:00\",\"message\":\"(chore) Cache playwright browsers (#1310)\",\"refs\":\"\",\"body\":\"* (chore) Cache playwright browsers\\r\\n\\r\\n* Bump @actions/cache version\\r\\n\\r\\n---------\\r\\n\\r\\nCo-authored-by: Dennis Kigen <kigen.work@gmail.com>\",\"authorName\":\"Jayasanka Weerasinghe\",\"authorEmail\":\"33048395+jayasanka-sack@users.noreply.github.com\"},{\"hash\":\"6dde099b26dac78ab04706a3c845c7ee41c6f1cd\",\"date\":\"2023-03-29T15:20:13+05:30\",\"message\":\"(feat) Patient lists UI and pagination improvements (#622)\",\"refs\":\"\",\"body\":\"* Added MyList UUID in the configuration\\r\\n\\r\\n* Fixed filters and added pagination to the patient list\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Responsiveness\\r\\n\\r\\n* Patient list pagination: Total results cached for proper navigation in pagination\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Mid\\r\\n\\r\\n* Show cohort type only in all lists and starred list\\r\\n\\r\\n* Review changes\",\"authorName\":\"Vineet Sharma\",\"authorEmail\":\"sharmava05@gmail.com\"},{\"hash\":\"d82b0aa451d082e070a0409e113d2ca150ff9395\",\"date\":\"2023-03-14T01:49:46-07:00\",\"message\":\"(chore) Cache dependencies in e2e workflow (#590)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"69a8193ab92c78747695b362be5183f1e93171d4\",\"date\":\"2023-03-10T23:55:43+03:00\",\"message\":\"(fix) O3-1922: Display patient list `name` in the breadcrumbs menu instead of a UUID (#586)\",\"refs\":\"\",\"body\":\"* display patient list name not uuid\\r\\n\\r\\n* update\\r\\n\\r\\n* final update\\r\\n\\r\\n* cache list name\\r\\n\\r\\n* remove caching\\r\\n\\r\\n* add error handling\\r\\n\\r\\n* improve error handling and naming\",\"authorName\":\"Jexsie\",\"authorEmail\":\"rayahaadiya@gmail.com\"},{\"hash\":\"8a6e153bc4af313754f4857a5b282951492ac344\",\"date\":\"2022-09-25T08:02:01+03:00\",\"message\":\"Update bundle-size.yml\",\"refs\":\"\",\"body\":\"Presently, our build script caches build artefacts, meaning that build comparisons would not yield any size differences. \\r\\n\\r\\nThis commit tweaks the command to skip caching so we can run distinct builds.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"4189443b687ecface921b5546febd54730e2ee4c\",\"date\":\"2022-05-17T11:21:24+03:00\",\"message\":\"(chore) Cache CI dependencies to speed up workflows (#205)\",\"refs\":\"\",\"body\":\"* (chore) Cache CI dependencies to speed up workflows\\r\\n\\r\\nThis PR sets up the [cache](https://github.com/actions/cache) GitHub action to enable dependency caching in this repository.\\r\\n\\r\\n* Commit orphaned translation string\\r\\n\\r\\n* Test cache\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":17}"}]}]},"parent_tool_use_id":null,"session_id":"016e43be-7f80-4a15-89b8-fee7fecf37c5","uuid":"dd06a1fa-dc77-4cc4-98d0-1e8faf91e731","timestamp":"2026-10-23T14:52:55.949Z","tool_use_result":[{"type":"text","text":"{\"commits\":[{\"hash\":\"dd5904929a290cb02803caa63066d44e3fc126a7\",\"date\":\"2026-09-20T23:31:10+03:00\",\"message\":\"(fix) Refresh patient list memberships after adding a patient\",\"refs\":\"\",\"body\":\"The add-to-list modal invalidated the cohort member key with the global\\nmutate imported from swr. That function is bound to SWR's default\\ncache, while every hook rendered under the framework's component\\ndecorator lives in the decorator's provider cache, so the call found\\nnothing and the patient's list memberships stayed stale after the\\nsuccess snackbar. Take mutate from useSWRConfig instead, which is bound\\nto the provider cache.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"212bc5dd4941ceb5dfd45a79417f345763fa0940\",\"date\":\"2026-09-18T17:00:58-04:00\",\"message\":\"(chore) Switch to using GitHub Actions cache for Actions\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"ian.c.bacher@gmail.com\"},{\"hash\":\"ac5758f3ba0c6868eb414e715e279e3e9d96ee90\",\"date\":\"2026-09-14T15:55:43-04:00\",\"message\":\"(fix) Make patient search a little more light-weight (#2742)\",\"refs\":\"\",\"body\":\"Basically this does two things:\\n\\n1. Fetch a smaller representation for a visit that includes the minimum\\n   we need.\\n2. Makes the SWR cache hold visits returned for 3 minutes. The idea\\n   being that paging through a single search shouldn't need to refetch\\n   the visit status unless the user genuinely switches their attention\\n   to elsewhere.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"b8335ad593a4946dd297a88e00c1fd6e6d1fc4f0\",\"date\":\"2026-09-08T20:40:11+08:00\",\"message\":\"(fix) O3-5940: Don't offer queues a patient is already in (#2710)\",\"refs\":\"\",\"body\":\"* (fix) O3-5940: Don't offer queues a patient is already in\\n\\n* (fix) O3-5940: Don't submit a prefilled service before the entries load\\n\\nA service prefilled from the dashboard was submittable while the lookup of the\\npatient's queue entries was still in flight: the queues had loaded, so the\\npriority defaulted and the form was valid behind the Service skeleton, and a\\nquick submit posted a queue entry that the filter would have excluded a moment\\nlater. The priority default now waits for those entries, so submitting during\\nthat window fails validation instead of reaching the server.\\n\\n* (fix) O3-5940: Let the Service field carry the queue filtering on its own\\n\\nFiltering whole locations out of the Location dropdown required a second,\\nunscoped useQueues() call just to group queues by location, plus a reset\\neffect to clear a location that disappeared underneath the user. Drop both\\nand filter only the Service options, which already load scoped to the\\nselected location. When the patient is in every queue there, the select\\nrenders empty with helper text saying so, and the required error is\\nsuppressed so it does not replace that text on blur. The misconfiguration\\nnotice now keys off the unfiltered queue list, and the priority skeleton\\nwaits on the queue entries alongside the services.\\n\\nDuplicate submissions come back as a generic \\\"Invalid Submission\\\" message\\nwith the identifying code in globalErrors, so getErrorMessage appends those\\ncodes and the queue fields reuse isDuplicateQueueEntryError instead of\\nmatching the message alone.\\n\\n* (fix) O3-5940: Address review feedback on duplicate detection and the Service field\\n\\nRead the duplicate error code from `globalErrors`, where the backend actually\\nreports it, and keep `getErrorMessage` free of it so the code no longer leaks\\ninto the snackbar subtitle two modals build from it. Let a genuine validation\\nerror still surface on the Service field, with the \\\"already in every queue\\\"\\nmessage carried as its error text rather than suppressing `invalid`.\\n\\nAlso make `patientUuid` optional, since every caller passes a value that may be\\nundefined, and drop the `memoizedQueueLocations` memo: `useFhirFetchAll` returns\\na fresh array on every render, so its dependency never matched and the memo\\nnever once returned a cached value.\\n\\n* Fix duplicate-queue error messages and prefilled service edge case\\n\\n- Read globalErrors from the backend response so validation errors like\\n  \\\"already in this queue\\\" surface instead of a generic message.\\n- Clear a prefilled service selection once queue entries confirm the\\n  patient is already enrolled in it.\\n\\n* (fix) O3-5940: Warn when the active queue entry lookup fails\\n\\n---------\\n\\nCo-authored-by: Nethmi Rodrigo <nethmi@openmrs.org>\\nCo-authored-by: NethmiRodrigo <nethmi.dilinika@gmail.com>\",\"authorName\":\"Ujjawal Prabhat\",\"authorEmail\":\"UjjawalPrabhat1@gmail.com\"},{\"hash\":\"39be6d5abb7182bd5b3e08b8684aefb6e046542f\",\"date\":\"2026-06-01T17:40:34-04:00\",\"message\":\"(feat) O3-5714: Improve performance with multi-paged patient search results (#2554)\",\"refs\":\"\",\"body\":\"* O3-5714: Improve performance with multi-paged patient search results\\n\\nSeveral notable fixes for the compact-patient-search component:\\n\\n* Previously, each call to `useSWRInfinite()` was, in essence, returning\\n  new copies of existing data, which lead to unnecessary re-renders. This\\n  has been fixed by setting `keepPreviousData` to `true`\\n* Previously, when `useSWRInfinite()` set `isLoading` to `true`, all\\n  results were replaced with placeholder. Since this gets set to `true`\\n  even when, e.g., loading a second page of results, this resulted in\\n  unnecessary unmounts and recreations, which was both a memory leak and\\n  lead to a stampede of requests.\\n* All search results were previously rendered and retained. This leads\\n  to stampedes of secondary queries (e.g., for patient photos, queue\\n  status, visit status, etc.). Instead, this PR moves us to using list\\n  virtualization so that roughly 10-18 items are retained in a React\\n  query. Large scrolls backwards or forwards have some slight glitches\\n  as components are re-rendered, but the easiest way to fix this is in\\n  the components rendering the secondary queries themselves.\\n* Recent patients, however, are not virtualized at all, as we rely on\\n  this being a limited list that is safe to load.\\n* A mistake in the call to `useArrowNavigation()` resulted in the arrow\\n  keys only being usable for up to the number of `recentPatients`\\n* This PR adds additional component-level memoization where it makes\\n  sense to speed up rendering. In addition, in the context of search\\n  results, we re-tune SWR to more aggressively cache so that there's\\n  less need to re-try, e.g., patient photo queries\\n* Additionally, this PR makes two fixes the service queues banner tag.\\n  First, if it is rendered outside the patient chart, a wrapper component\\n  is used so no query needs to be issued. Second, the query that was\\n  used overfetched data, especially as the queue details in the modal\\n  are basically reloaded, so the representation has been updated to\\n  minimize the data requested. This is one of the biggest contributing\\n  components.\\n\\n* Fixes from code review\\n\\n* Address Copilot comment\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"47d2f46e9584bb21e616f22c67e3315c985bc433\",\"date\":\"2026-04-27T21:07:35-09:00\",\"message\":\"(fix) O3-5579: Isolate appointment cache per patient to prevent cross-patient data leakage (#2450)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"omeri innocent\",\"authorEmail\":\"innocentomeri08@gmail.com\"},{\"hash\":\"8a16c8613ca23503da3093165282cdfa5a6ad3a2\",\"date\":\"2026-03-04T00:15:13+03:00\",\"message\":\"(fix) Refresh queue banner on patient chart after serving (#2295)\",\"refs\":\"\",\"body\":\"When navigating to the patient chart after serving a queue entry,\\nthe patient banner showed stale queue information because the\\nuseQueueEntries hook returned cached SWR data before revalidation\\ncompleted. Dispatch `queue-entry-updated` on mount (gated to the\\npatient-chart context) so the hook refetches fresh data, matching\\nthe pattern already used by DefaultQueueTable.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"69634fa859a4dd50d67b02ac789de5e0476e2979\",\"date\":\"2026-02-18T16:54:24+03:00\",\"message\":\"(fix) O3-5433: Prevent stale queue-entry modal submissions (#2274)\",\"refs\":\"\",\"body\":\"* (fix) O3-5433: Prevent stale queue-entry modal submissions\\n\\nThe Move/Transition/Edit queue entry action modals received a queue entry\\nobject captured at table render time. If another user, browser tab, or\\nbackground task ended that entry before the modal was submitted, the backend\\nwould reject the request with a 500 error \\\"Cannot transition a queue entry\\nthat has already ended\\\".\\n\\nThis change adds stale-entry detection at modal open and on submit to prevent\\nthe above scenario. Specifically, it makes the following changes:\\n\\n- Prefetch queue entry by UUID on modal open; show loading/error/ended\\n  states and block the form when the entry is no longer active\\n- Refresh queue-entry caches when stale ended entries are detected\\n- Catch already-ended errors on submit as a fallback; warn, refresh, and\\n  close the modal\\n- Add synchronous submit re-entry guards (useRef) in action and confirm\\n  modals to prevent duplicate submissions\\n- Centralize queue-entry error parsing into `queue-entry-error.utils.ts`\\n- Extract shared queue-entry custom representation constant to avoid\\n  duplicate encoding\\n- Add tests for Move/Transition/Edit stale-entry gating and already-ended\\n  submit handling\\n\\n* (fix) Use getCoreTranslation for 'Close' button text\\n\\n\\\"Close\\\" is a common string already provided by the framework's core\\ntranslations. Use getCoreTranslation('close') instead of a local\\nt('close', 'Close') call to avoid duplicating the translation key\\nin this package.\\n\\n* (fix) Address review feedback\\n\\nStabilize useMutateQueueEntries by wrapping the returned function in\\nuseCallback and the return object in useMemo, so consumers get a stable\\nreference. This removes the eslint-disable-next-line workarounds in the\\nthree action modals.\\n\\nRemove the redundant isSubmittingRef double-submit guard from\\nQueueEntryActionModal and QueueEntryConfirmActionModal. The existing\\ndisabled={isSubmitting} state is sufficient to prevent duplicate\\nsubmissions.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"eb79923a3297dbdc677c87f2cb7236f6ba43a844\",\"date\":\"2025-09-11T00:13:04+03:00\",\"message\":\"(chore) Modernize GitHub Actions workflows\",\"refs\":\"\",\"body\":\"- Replace manual caching with built-in Node.js cache\\n- Standardize Node.js version format to '20.x'\\n- Simplify Playwright installation process\\n- Add descriptive step names with emojis\\n\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"1035f45ff4a778664d6d629a7679fc43046877a1\",\"date\":\"2025-09-09T17:10:56+03:00\",\"message\":\"(fix) O3-5014: Surface actual error messages from appointment status change API (#1963)\",\"refs\":\"\",\"body\":\"Previously, when users attempted to cancel missed appointments, generic error messages were displayed instead of the specific backend validation errors. Now the actual API exception message is properly extracted and shown to users.\\n\\n- Extract error messages from responseBody.error.message chain\\n- Remove square brackets from backend error formatting\\n- Surface specific validation errors like \\\"Appointment status can not be changed from Missed to Cancelled\\\"\\n- Fix SWR cache invalidation issues causing premature UI updates\\n- Enable retry capability by resetting loading state in error handler\\n- Modernize error handling with async/await pattern\\n\\nFixes issue where backend validation errors (e.g., missed appointments cannot be cancelled due to status sequence rules) were not properly communicated to users.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"bc9848228e577b6d480f8ab7a91abcf61941e884\",\"date\":\"2024-09-16T22:11:23+03:00\",\"message\":\"(chore) Set up local turborepo cache server for pre-release job\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"4e8fe5871828599ae51962c42f2fc7a86f8f27f7\",\"date\":\"2024-09-06T11:43:24+03:00\",\"message\":\"(chore) Cache playwright browsers (#1310)\",\"refs\":\"\",\"body\":\"* (chore) Cache playwright browsers\\r\\n\\r\\n* Bump @actions/cache version\\r\\n\\r\\n---------\\r\\n\\r\\nCo-authored-by: Dennis Kigen <kigen.work@gmail.com>\",\"authorName\":\"Jayasanka Weerasinghe\",\"authorEmail\":\"33048395+jayasanka-sack@users.noreply.github.com\"},{\"hash\":\"6dde099b26dac78ab04706a3c845c7ee41c6f1cd\",\"date\":\"2023-03-29T15:20:13+05:30\",\"message\":\"(feat) Patient lists UI and pagination improvements (#622)\",\"refs\":\"\",\"body\":\"* Added MyList UUID in the configuration\\r\\n\\r\\n* Fixed filters and added pagination to the patient list\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Responsiveness\\r\\n\\r\\n* Patient list pagination: Total results cached for proper navigation in pagination\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Updated translations\\r\\n\\r\\n* Mid\\r\\n\\r\\n* Show cohort type only in all lists and starred list\\r\\n\\r\\n* Review changes\",\"authorName\":\"Vineet Sharma\",\"authorEmail\":\"sharmava05@gmail.com\"},{\"hash\":\"d82b0aa451d082e070a0409e113d2ca150ff9395\",\"date\":\"2023-03-14T01:49:46-07:00\",\"message\":\"(chore) Cache dependencies in e2e workflow (#590)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"69a8193ab92c78747695b362be5183f1e93171d4\",\"date\":\"2023-03-10T23:55:43+03:00\",\"message\":\"(fix) O3-1922: Display patient list `name` in the breadcrumbs menu instead of a UUID (#586)\",\"refs\":\"\",\"body\":\"* display patient list name not uuid\\r\\n\\r\\n* update\\r\\n\\r\\n* final update\\r\\n\\r\\n* cache list name\\r\\n\\r\\n* remove caching\\r\\n\\r\\n* add error handling\\r\\n\\r\\n* improve error handling and naming\",\"authorName\":\"Jexsie\",\"authorEmail\":\"rayahaadiya@gmail.com\"},{\"hash\":\"8a6e153bc4af313754f4857a5b282951492ac344\",\"date\":\"2022-09-25T08:02:01+03:00\",\"message\":\"Update bundle-size.yml\",\"refs\":\"\",\"body\":\"Presently, our build script caches build artefacts, meaning that build comparisons would not yield any size differences. \\r\\n\\r\\nThis commit tweaks the command to skip caching so we can run distinct builds.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"4189443b687ecface921b5546febd54730e2ee4c\",\"date\":\"2022-05-17T11:21:24+03:00\",\"message\":\"(chore) Cache CI dependencies to speed up workflows (#205)\",\"refs\":\"\",\"body\":\"* (chore) Cache CI dependencies to speed up workflows\\r\\n\\r\\nThis PR sets up the [cache](https://github.com/actions/cache) GitHub action to enable dependency caching in this repository.\\r\\n\\r\\n* Commit orphaned translation string\\r\\n\\r\\n* Test cache\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":17}"}],"tool_result_meta":[{"id":"toolu_01QWYwNRbdjqxqV18wz668xr","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
