{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_019Y1DxrDgtoiAsJ8QkyTv3K","type":"tool_result","content":[{"type":"text","text":"{\"commits\":[{\"hash\":\"549c8a2165dce773cc63343bf48d7ebbd43d942f\",\"date\":\"2026-10-05T18:35:42-04:00\",\"message\":\"(chore) Stop generating unused build manifests (#1935)\",\"refs\":\"\",\"body\":\"Remove StatsWriterPlugin from the Webpack and Rspack configurations so builds no longer emit *.buildmanifest.json. These manifests supported offline mode and are no longer consumed by core.\\n\\nRemove the unused webpack-stats-plugin dependency from both configuration packages and the openmrs CLI, and update the lockfile.\\nCoordinate rollout with patient-chart’s Angular form-entry app, whose custom Webpack configuration still imports this plugin through the tooling’s transitive dependency.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"a62f8164991a64135f438cef848fdc751e866d20\",\"date\":\"2026-09-28T14:08:46-04:00\",\"message\":\"(BREAKING) Remove offline & rxjs support from framework (#1894)\",\"refs\":\"\",\"body\":\"* (BREAKING) Remove offline & rxjs support from framework\\n\\nRetains a small compatibility shim with the most commonly-used public\\nfunctions now stubbed. These deprecated shims will be removed in a\\nfuture version.\\n\\nThe biggest breaking change is the framework no longer supports rxjs\\ndirectly. Functions that returned Observables now return Promises. A\\nsmall compatibility patch is provided for the notifications system.\\n\\n* Fix `getCurrentUser`'s opts\\n\\n* Remove isLoginEnabled\\n\\n* Sounder re-implementation of getCurrentUser()\\n\\n* Remove more stuff, add back a couple of drop APIs we need, and re-add mocks\\n\\n* More clean-up\\n\\n* Add a changeset gentle-jars-pull.md\\n\\n* (chore) Add docs\\n\\n* Clean-up README and _main-content.scss\\n\\n* Fixup changesets\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"4a09251b00d884b956ade12f6a3388eabe38e875\",\"date\":\"2025-10-03T20:28:04+03:00\",\"message\":\"(chore) Bump ace-builds and configure for webpack 5 with local worker bundling (#1472)\",\"refs\":\"\",\"body\":\"Upgrades ace-builds from 1.4.14 to 1.43.3 and react-ace from 9.5.0 to 14.0.1. Configures JSON worker to bundle locally using webpack 5's\\nasset modules (new URL() syntax) for offline compatibility in healthcare environments. This approach avoids both CDN dependencies and\\nthe deprecated file-loader package.\\n\\nSources: https://github.com/ajaxorg/ace-builds/issues/211\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":3}"}]}]},"parent_tool_use_id":null,"session_id":"016e43be-7f80-4a15-89b8-fee7fecf37c5","uuid":"62762533-8feb-4373-8a9b-bb921c883dbe","timestamp":"2026-10-23T14:52:59.692Z","tool_use_result":[{"type":"text","text":"{\"commits\":[{\"hash\":\"549c8a2165dce773cc63343bf48d7ebbd43d942f\",\"date\":\"2026-10-05T18:35:42-04:00\",\"message\":\"(chore) Stop generating unused build manifests (#1935)\",\"refs\":\"\",\"body\":\"Remove StatsWriterPlugin from the Webpack and Rspack configurations so builds no longer emit *.buildmanifest.json. These manifests supported offline mode and are no longer consumed by core.\\n\\nRemove the unused webpack-stats-plugin dependency from both configuration packages and the openmrs CLI, and update the lockfile.\\nCoordinate rollout with patient-chart’s Angular form-entry app, whose custom Webpack configuration still imports this plugin through the tooling’s transitive dependency.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"a62f8164991a64135f438cef848fdc751e866d20\",\"date\":\"2026-09-28T14:08:46-04:00\",\"message\":\"(BREAKING) Remove offline & rxjs support from framework (#1894)\",\"refs\":\"\",\"body\":\"* (BREAKING) Remove offline & rxjs support from framework\\n\\nRetains a small compatibility shim with the most commonly-used public\\nfunctions now stubbed. These deprecated shims will be removed in a\\nfuture version.\\n\\nThe biggest breaking change is the framework no longer supports rxjs\\ndirectly. Functions that returned Observables now return Promises. A\\nsmall compatibility patch is provided for the notifications system.\\n\\n* Fix `getCurrentUser`'s opts\\n\\n* Remove isLoginEnabled\\n\\n* Sounder re-implementation of getCurrentUser()\\n\\n* Remove more stuff, add back a couple of drop APIs we need, and re-add mocks\\n\\n* More clean-up\\n\\n* Add a changeset gentle-jars-pull.md\\n\\n* (chore) Add docs\\n\\n* Clean-up README and _main-content.scss\\n\\n* Fixup changesets\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"4a09251b00d884b956ade12f6a3388eabe38e875\",\"date\":\"2025-10-03T20:28:04+03:00\",\"message\":\"(chore) Bump ace-builds and configure for webpack 5 with local worker bundling (#1472)\",\"refs\":\"\",\"body\":\"Upgrades ace-builds from 1.4.14 to 1.43.3 and react-ace from 9.5.0 to 14.0.1. Configures JSON worker to bundle locally using webpack 5's\\nasset modules (new URL() syntax) for offline compatibility in healthcare environments. This approach avoids both CDN dependencies and\\nthe deprecated file-loader package.\\n\\nSources: https://github.com/ajaxorg/ace-builds/issues/211\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":3}"}],"tool_result_meta":[{"id":"toolu_019Y1DxrDgtoiAsJ8QkyTv3K","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
